func TestParseYAMLBool(t *testing.T) {
	tests := []struct {
		input    string
		wantVal  bool
		wantErr  bool
	}{
		{"true", true, false},
		{"false", false, false},
		{"1", true, false},
		{"0", false, false},
		{"yes", true, false},
		{"no", false, false},
		{"on", true, false},
		{"off", false, false},
		{"True", true, false},
		{"FALSE", false, false},
		{"  yes  ", true, false},
		{"maybe", false, true},
		{"certainly", false, true},
		{"", false, true},
	}

	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			got, err := parseYAMLBool(tt.input)
			if tt.wantErr {
				if err == nil {
					t.Errorf("parseYAMLBool(%q) = _, nil; want error", tt.input)
				}
			} else {
				if err != nil {
					t.Errorf("parseYAMLBool(%q) = _, %v; want no error", tt.input, err)
				}
				if got != tt.wantVal {
					t.Errorf("parseYAMLBool(%q) = %v; want %v", tt.input, got, tt.wantVal)
				}
			}
		})
	}
}

